style.css:
@-moz-document url-prefix("https://www.roblox.com/") {
/* Background image */
  body {
    background: url("https://i.imgur.com/XGQbXUg.jpeg") no-repeat center center fixed !important;
    background-size: cover !important;
    font-family: "Segoe UI", sans-serif !important;
  }

  /* Make content area semi-transparent */
  .container-main, .navbar, .footer, .content, .game-home-page, .section, .game-card-container {
    background-color: rgba(255, 255, 255, 0.8) !important;
    border-radius: 12px !important;
    box-shadow: 0 0 10px rgba(0,0,0,0.2) !important;
  }

  /* Change link colors */
  a {
    color: #a347a6 !important;
  }

  a:hover {
    color: #e86fe6 !important;
  }

  /* Customize buttons */
  .btn-primary, .btn-secondary, .btn-control-md {
    background-color: #a347a6 !important;
    border: none !important;
    color: white !important;
    transition: 0.3s;
  }

  .btn-primary:hover, .btn-secondary:hover {
    background-color: #e86fe6 !important;
  }

  /* Change text colors */
  h1, h2, h3, h4, h5, h6, p, span {
    color: #2d2d2d !important;
  }

  /* Hide annoying ads or elements */
  .ads-container, .top-ad, .ad-slot, .game-card-ad {
    display: none !important;
  }

  /* Round off avatars and icons for a softer look */
  .avatar-card-image, .thumbnail-2d-container, .game-card-thumb {
    border-radius: 16px !important;
  }

  /* Scrollbar styling */
  ::-webkit-scrollbar {
    width: 10px;
  }

  ::-webkit-scrollbar-track {
    background: rgba(255,255,255,0.3);
  }

  ::-webkit-scrollbar-thumb {
    background-color: #a347a6;
    border-radius: 10px;
  }
}
